        return GOCARDLESS_ACTION_TO_MANDATE_STATE.getOrDefault(event.getAction(), MandateState.UNKNOWN);
    }

    public MandateState mapEventToMandateStateAndUpdate(GoCardlessEvent event, DirectDebitStateWithDetails state) {
        Optional<MandateState> mandateState = mapEventToMandateState(event);
        if (!mandateState.isPresent()) {
            throw new IllegalArgumentException("Unknown GoCardless event action: " + event.getAction());
        }
        MandateState newMandateState = mandateState.get();
        state.setMandateState(newMandateState);
        return newMandateState;
    }
}

