public static InitRequestPayload from(RawMessage message) {
    Preconditions.checkArgument(message.getLength() == 8, "Invalid message length");
    byte[] data = message.getData();
    return ImmutableInitRequestPayload.builder()
            .version(data[0])
            .challenge(data[1])
            .flags(data[2])
            .reserved(data[3])
            .maxResponseLength(data[4] & 0x7F)
            .reserved2(data[5])
            .reserved3(data[6])
            .checksum(data[7])
            .build();
}

